ip4_coup.1 = {
	type = country_event
	placement = root

	duration = 3

	title = ip4_coup.1.t
	desc = {
		first_valid = {
			triggered_desc = {
				desc = ip4_coup.1.d_1
				trigger = {
					var:coup_reason_var ?= 1
				}
			}
			triggered_desc = {
