				limit = {
					is_pop_type = soldiers
				}
				add = {
					value = 3
					desc = "POP_SOLDIERS"
				}
			}
			else = {
				add = {
					value = 2
					desc = "LOWER_NO_ICON"
				}
			}
			if = {
				limit = {
					OR = {
						is_pop_type = clerks
						is_pop_type = soldiers
					}
					owner = {
						number_of_claims > 0
					}
