				desc = "POP_RADICALS"
				value = pop_radical_fraction
				multiply = 2
				add = 1
			}
		}
		else = {
			multiply = { # Multiplied by 1.5x max
				desc = "POP_RADICALS"
				value = pop_radical_fraction
				divide = 2
				add = 1
			}
		}
	}

