			desc = "URBAN_STATE" # Increases support in rural states, decreases in urban
			value = 0.5
			subtract = state.state_urbanization_rate
			multiply = 10
		}

		add = {
			desc = "POP_LOYALISTS" # Increases support amongst loyal pops
			value = pop_loyalist_fraction
			multiply = 10
		}

		if = {
			limit = {
				is_pop_type = aristocrats
			}
			add = {
				value = 25
				desc = "POP_ARISTOCRATS"
			}
		}
		else_if = {
			limit = {
				is_pop_type = farmers
			}
			add = {
				value = 10
				desc = "POP_FARMERS"
			}
		}
		else_if = {
			limit = {
				is_pop_type = officers
			}
			add = {
				value = 35
				desc = "POP_OFFICERS"
			}
		}
		else_if = {
			limit = {
				is_pop_type = soldiers
			}
			add = {
				value = 5
				desc = "POP_SOLDIERS"
			}
		}
		else_if = {
			limit = {
				is_pop_type = peasants
			}
			add = {
				value = 10
				desc = "POP_PEASANTS"
			}
		}

		if = {
			limit = {
				owner ?= {
					has_law = law_type:law_monarchy
				}
				owner.ruler ?= {
					NOT = { has_trait = trait_child }
					law_stance = {
						law = law_type:law_autocracy
						value > neutral
					}
				}
			}
			multiply = { # Popularity of the Shogun
				add = owner.ruler.popularity
				multiply = 0.01
				add = 1
				min = 0.2
				max = 1.8
				desc = "RULER_POPULARITY"
			}
		}
		else_if = {
			limit = {
				owner ?= {
					has_law = law_type:law_monarchy
				}
				owner.ruler ?= {
					has_trait = trait_child
					law_stance = {
						law = law_type:law_autocracy
						value > neutral
					}
				}
			}
			multiply = {
				value = 0.75
				desc = "RULER_IS_CHILD"
			}
		}

		multiply = { # Illiterate pops participate at 1/10 the rate of fully literate pops
			desc = "POP_LITERACY"
			value = literacy_rate
			add = 0.2
			max = 0.7 # Starts more powerful but caps out early
		}

		if = {
			limit = {
				owner = {
					has_variable = wargoal_enforced_by_recognized_power
				}
			}
			multiply = {
				value = 0.75
				desc = "wargoal_pressed_by_recognized_power_tt"
			}
		}

		multiply = { # Daimyo loyalty is quite important
			value = 0.5
			add = state.state_daimyo_loyalty
			desc = "LOYALTY_OF_STATE_DAIMYO"
		}
	}

	revolution = {
		possible = {
			political_movement_support >= 0.05
		}

		weight = {
			value = 100
		}

		state_weight = {
			if = {
				limit = {
					state_daimyo_loyalty_impact_tokugawa > 0
				}
				add = state_daimyo_loyalty_impact_tokugawa
			}
			else = {
				multiply = 0
			}
		}
	}

	# Cannot secede

	additional_radicalism_factors = {
		owner ?= {
			if = {
				limit = {
					has_law = law_type:law_monarchy
				}
				if = {
					limit = {
						OR = {
							is_enacting_law = law_type:law_presidential_republic
							is_enacting_law = law_type:law_parliamentary_republic
							is_enacting_law = law_type:law_corporate_state
							is_enacting_law = law_type:law_theocracy
							is_enacting_law = law_type:law_council_republic
						}
					}

					add = {
						value = 0.25
						desc = "MONARCHY_BEING_ABOLISHED"
					}
				}
			}
			if = {
				limit = {
					NOT = {
						has_law = law_type:law_bakufu
					}
					NOT = {
						any_interest_group = {
							is_in_government = yes
							leader = {
								has_variable = house_tokugawa
							}
						}
					}
				}
				add = {
					desc = "tokugawa_not_in_government_tt"
					value = 0.25
				}
			}
		}
		if = {
			limit = {
				this.days_since_movement_defeated <= very_long_modifier_time
			}
			add = { # (x-y)/y - ([1, 7300]-7300)/7300
				desc = "movement_suppressed_after_civil_war"
				value = this.days_since_movement_defeated
				subtract = very_long_modifier_time
				divide = {
					value = very_long_modifier_time
				}
			}
		}
	}
}

